// Position-based cloth. The top edge is pinned and neighboring particles
// preserve their rest lengths. A fixed simulation step makes seeking repeatable.
export function clothGeometry(geometry) {
  const positions = geometry.attributes.position;
  const rest = new Float32Array(positions.array),
    previous = new Float32Array(rest);
  const columns = geometry.parameters.widthSegments + 1;
  const edges = [];
  for (let n = 0; n < positions.count; n++) {
    if (n % columns) edges.push([n - 1, n, 1 / (columns - 1)]);
    if (n >= columns)
      edges.push([n - columns, n, 1 / geometry.parameters.heightSegments]);
  }
  let tick = 0,
    cycle = -1;
  return (time) => {
    const period = 4,
      epoch = Math.floor(time / period);
    const target = Math.floor((time - epoch * period) * 60);
    const a = positions.array;
    if (epoch !== cycle || target < tick) {
      a.set(rest);
      previous.set(rest);
      tick = 0;
      cycle = epoch;
    }
    while (tick < target) {
      tick++;
      for (let n = columns; n < positions.count; n++) {
        const i = n * 3;
        const wind =
          0.0014 * Math.sin(rest[i] * 5 + tick / 18) +
          0.0007 * Math.cos(rest[i + 1] * 6 - tick / 17);
        for (let j = 0; j < 3; j++) {
          const x = a[i + j];
          a[i + j] +=
            (x - previous[i + j]) * 0.981 +
            (j === 2 ? wind : j === 1 ? -0.0011 : 0.00015);
          previous[i + j] = x;
        }
      }
      for (let pass = 0; pass < 4; pass++)
        for (const [m, n, length] of edges) {
          const i = m * 3,
            j = n * 3,
            dx = a[j] - a[i],
            dy = a[j + 1] - a[i + 1],
            dz = a[j + 2] - a[i + 2];
          const distance = Math.hypot(dx, dy, dz) || length;
          const factor = (1 - length / distance) / (m < columns ? 1 : 2);
          if (m >= columns) {
            a[i] += dx * factor;
            a[i + 1] += dy * factor;
            a[i + 2] += dz * factor;
          }
          if (n >= columns) {
            a[j] -= dx * factor;
            a[j + 1] -= dy * factor;
            a[j + 2] -= dz * factor;
          }
        }
    }
    positions.needsUpdate = true;
  };
}

'use client';
import { createElement as h, useEffect, useRef, useState } from "react";
import { mountScene } from "./scene.js";

export function createImageEffect(name, effect) {
  function Template(props) {
    const host = useRef(null),
      current = useRef(props);
    current.current = props;
    const [status, setStatus] = useState("");
    const inputs = JSON.stringify(props.images ?? []);
    const depthInputs = JSON.stringify(name === "PhantomGrid" ? props.depthMaps ?? [] : []);
    useEffect(() => {
      const sources = JSON.parse(inputs);
      if (!sources.length) {
        setStatus("Supply at least one image.");
        return;
      }
      setStatus("Loading images…");
      try {
        return mountScene(
          host.current,
          effect,
          sources,
          current,
          setStatus,
          JSON.parse(depthInputs),
        );
      } catch (error) {
        setStatus(error.message);
      }
    }, [inputs, depthInputs]);
    return h(
      "div",
      {
        className: props.className,
        style: {
          position: "relative",
          aspectRatio: "16/9",
          background: "#161819",
          ...props.style,
        },
      },
      h("div", {
        ref: host,
        role: effect.count > 1 || effect.activate ? "group" : "img",
        "aria-label": props.label ?? name,
        style: { position: "absolute", inset: 0, overflow: "hidden" },
      }),
      status &&
        h(
          "span",
          {
            role: "status",
            style: {
              position: "absolute",
              inset: 12,
              color: "white",
              pointerEvents: "none",
            },
          },
          status,
        ),
    );
  }
  Template.displayName = name;
  return Template;
}

import * as THREE from "three";

// Sculpt a relief surface over an elliptical head, then sample it as points.
export function particlePortrait() {
  const positions = [], uv = [];
  const bump = (x, y, cx, cy, rx, ry) =>
    Math.exp(-(((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2));
  for (let row = 0; row < 88; row++) {
    const y = (row / 87) * 2 - 1;
    for (let col = 0; col < 64; col++) {
      const x = ((col + (row % 2) * 0.5) / 64) * 2 - 1;
      const shell = 1 - x * x - y * y;
      if (shell <= 0) continue;
      const eyes =
        bump(x, y, -0.35, 0.2, 0.2, 0.12) + bump(x, y, 0.35, 0.2, 0.2, 0.12);
      const nose = bump(x, y, 0, 0, 0.14, 0.36);
      const lips = bump(x, y, 0, -0.4, 0.34, 0.095);
      const z =
        Math.sqrt(shell) * 0.21 + nose * 0.1 - eyes * 0.052 + lips * 0.035;
      uv.push((x + 1) / 2, (y + 1) / 2);
      positions.push(x * (0.23 + 0.025 * y), y * 0.34, z);
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(positions, 3),
  );
  geometry.setAttribute("uv", new THREE.Float32BufferAttribute(uv, 2));
  const material = new THREE.ShaderMaterial({
    transparent: true, depthWrite: false,
    uniforms: {
      image: {value: null}, depthMap: {value: null}, hasDepth: {value: false},
      opacity: {value: 1}, pointSize: {value: 2}, cursor: {value: new THREE.Vector2(.5,.5)}
    },
    vertexShader: `
      uniform sampler2D image, depthMap;
      uniform bool hasDepth;
      uniform vec2 cursor;
      uniform float pointSize;
      varying vec3 tint;
      varying float mask;
      void main(){
        vec3 p=position;
        float relief=hasDepth ? texture2D(depthMap,uv).r : p.z;
        mask=hasDepth ? smoothstep(.01,.05,relief) : 1.;
        if(hasDepth) p.z=relief*.28;
        vec2 delta=uv-cursor;
        p.xy+=delta*.09*exp(-dot(delta,delta)*32.);
        tint=texture2D(image,uv).rgb;
        vec4 view=modelViewMatrix*vec4(p,1.);
        gl_Position=projectionMatrix*view;
        gl_PointSize=clamp(pointSize/-view.z,1.,8.);
      }`,
    fragmentShader: `
      uniform float opacity;
      varying vec3 tint;
      varying float mask;
      void main(){
        float radius=length(gl_PointCoord-.5);
        if(radius>.5 || mask<.01) discard;
        gl_FragColor=vec4(tint,opacity*mask*(1.-smoothstep(.32,.5,radius)));
        #include <colorspace_fragment>
      }`
  });
  const face = new THREE.Points(geometry, material);
  face.position.z = 0.22;
  return face;
}

export const full = (s) => ({ w: s.aspect, h: 1 });

export const strip = (s) => ({ x: s.offset * 0.82, w: 0.75, h: 0.78 });

export const grid = (s) => {
  const col = s.slot % 7,
    row = Math.floor(s.slot / 7);
  return {
    x: (col - 3 - s.phase) * 0.49,
    y: (row - 2 - s.verticalPhase) * 0.36,
    textureIndex: Math.floor(s.travel) + col + 7 * (row + s.verticalBase),
    w: 0.46,
    h: 0.33,
  };
};

